import{_ as d,S as l,n as c,p as u,q as t,J as a,C as s,A as n,a2 as r}from"./framework-c4fdf794.js";const h={},p={class:"table-of-contents"},m={class:"warning custom-block"};function g(v,e){const i=l("router-link"),o=l("RouterLink");return c(),u("div",null,[e[23]||(e[23]=t("h1",{id:"l7-rate-limiter",tabindex:"-1"},[t("a",{class:"header-anchor",href:"#l7-rate-limiter","aria-hidden":"true"},"#"),a(" L7 Rate Limiter")],-1)),t("nav",p,[t("ul",null,[t("li",null,[s(i,{to:"#overview"},{default:n(()=>[...e[0]||(e[0]=[a("Overview",-1)])]),_:1})]),t("li",null,[s(i,{to:"#how-it-works"},{default:n(()=>[...e[1]||(e[1]=[a("How it works",-1)])]),_:1})]),t("li",null,[s(i,{to:"#prerequisites"},{default:n(()=>[...e[2]||(e[2]=[a("Prerequisites",-1)])]),_:1})]),t("li",null,[s(i,{to:"#enabling-and-disabling-the-rate-limiter"},{default:n(()=>[...e[3]||(e[3]=[a("Enabling and disabling the rate limiter",-1)])]),_:1})]),t("li",null,[s(i,{to:"#default-settings"},{default:n(()=>[...e[4]||(e[4]=[a("Default settings",-1)])]),_:1})]),t("li",null,[s(i,{to:"#actions"},{default:n(()=>[...e[5]||(e[5]=[a("Actions",-1)])]),_:1})]),t("li",null,[s(i,{to:"#managing-rules"},{default:n(()=>[...e[6]||(e[6]=[a("Managing rules",-1)])]),_:1})]),t("li",null,[s(i,{to:"#domain-patterns"},{default:n(()=>[...e[7]||(e[7]=[a("Domain patterns",-1)])]),_:1})]),t("li",null,[s(i,{to:"#testing-which-rule-matches"},{default:n(()=>[...e[8]||(e[8]=[a("Testing which rule matches",-1)])]),_:1})]),t("li",null,[s(i,{to:"#monitoring"},{default:n(()=>[...e[9]||(e[9]=[a("Monitoring",-1)])]),_:1})])])]),e[24]||(e[24]=r('<h2 id="overview" tabindex="-1"><a class="header-anchor" href="#overview" aria-hidden="true">#</a> Overview</h2><p>The <strong>L7 Rate Limiter</strong> is a WebShield feature that lets a server administrator limit how many HTTP requests a single client (IP address) may send within a time window. It counts requests <strong>per client IP</strong> over a <strong>sliding time window</strong> and, once a client exceeds the limit, applies a configurable <strong>action</strong>: let the request pass, allow it past the remaining WebShield checks, deny it outright, or serve a <strong>JavaScript splash challenge</strong>.</p>',2)),t("p",null,[e[11]||(e[11]=a("The limiter is evaluated ",-1)),e[12]||(e[12]=t("strong",null,"first",-1)),e[13]||(e[13]=a(" on every request WebShield inspects — before ",-1)),s(o,{to:"/features/under_attack_mode/"},{default:n(()=>[...e[10]||(e[10]=[a("Under Attack Mode",-1)])]),_:1}),e[14]||(e[14]=a(", the GreyList / Anti-bot Challenge, and the ModSecurity rules — so it stops request floods before they consume any further processing.",-1))]),e[25]||(e[25]=t("p",null,[a("The L7 Rate Limiter is a "),t("strong",null,"server-wide administrator feature"),a(". It is distinct from Under Attack Mode: UAM challenges "),t("strong",null,"every"),a(" visitor of a protected domain, while the rate limiter acts only on clients that send "),t("strong",null,"too many"),a(" requests, and it can target traffic by source IP as well as by domain.")],-1)),e[26]||(e[26]=t("div",{class:"tip custom-block"},[t("p",{class:"custom-block-title"},"When to use it"),t("p",null,"Use the L7 Rate Limiter to cap abusive request rates without affecting normal visitors — for example to slow down scraping and brute-force attempts against a busy domain, throttle a misbehaving subnet, or put an automatic challenge in front of any client that floods the server.")],-1)),t("div",m,[e[22]||(e[22]=t("p",{class:"custom-block-title"},"Availability depends on the environment",-1)),t("p",null,[e[16]||(e[16]=a("The L7 Rate Limiter is not available on every environment WebShield supports. Before relying on it, check whether the current server supports it by running ",-1)),e[17]||(e[17]=t("span",{class:"notranslate"},[t("code",null,"imunify360-wsctl filters")],-1)),e[18]||(e[18]=a(" and confirming the ",-1)),e[19]||(e[19]=t("span",{class:"notranslate"},[t("code",null,"l7prot")],-1)),e[20]||(e[20]=a(" filter is listed as available — see ",-1)),s(o,{to:"/command_line_interface/#webshield-feature-availability"},{default:n(()=>[...e[15]||(e[15]=[a("WebShield feature availability",-1)])]),_:1}),e[21]||(e[21]=a(".",-1))])]),e[27]||(e[27]=r(`<h2 id="how-it-works" tabindex="-1"><a class="header-anchor" href="#how-it-works" aria-hidden="true">#</a> How it works</h2><ul><li>Traffic is matched against an ordered list of <strong>rules</strong>. A rule pairs a scope — source <strong>IPs</strong> (addresses or CIDR networks) and/or <strong>domains</strong> (exact names or wildcard patterns) — with a <strong>rate</strong> (<code>limit</code> per <code>timeframe</code>) and an <strong>action</strong> to apply once the rate is exceeded.</li><li>Rules are evaluated in the order shown by <span class="notranslate"><code>l7prot list</code></span>, and the <strong>first matching rule wins</strong>. A client that stays within the matched rule&#39;s limit proceeds through the normal WebShield flow.</li><li>Requests from clients that match <strong>no rule</strong> are counted against the <strong>default settings</strong> — a catch-all rate limit that applies server-wide (see <a href="#default-settings">Default settings</a>).</li><li>Requests are counted <strong>per rule, per client IP</strong>. All domains covered by one rule share a single counter for a given client, so a bot cannot reset its budget by spreading requests across subdomains.</li><li>Counters are <strong>persistent</strong>: editing a rule, toggling the service, or restarting WebShield does not reset a client&#39;s request count.</li><li>All management is <strong>live</strong>: every change made with the CLI applies to traffic immediately — no configuration file to edit and no service reload or restart required.</li><li>The feature is gated behind a single on/off toggle that is <strong>off by default</strong>, and all its state is stored on the server itself.</li></ul><h2 id="prerequisites" tabindex="-1"><a class="header-anchor" href="#prerequisites" aria-hidden="true">#</a> Prerequisites</h2><ul><li>WebShield version &gt;= 1.46.0 installed and running in an environment where the L7 Rate Limiter is available (see the note above).</li><li>Root access to the server. The rate limiter is managed with the <span class="notranslate"><code>imunify360-wsctl l7prot</code></span> command, which must be run as <code>root</code>.</li></ul><h2 id="enabling-and-disabling-the-rate-limiter" tabindex="-1"><a class="header-anchor" href="#enabling-and-disabling-the-rate-limiter" aria-hidden="true">#</a> Enabling and disabling the rate limiter</h2><p>The L7 Rate Limiter is <strong>off by default</strong>. Enable the feature before managing rules — while it is disabled, all other <span class="notranslate"><code>l7prot</code></span> commands fail with a <code>service_disabled</code> error (only <span class="notranslate"><code>l7prot service</code></span> always works, so the feature can always be turned back on).</p><div class="notranslate"><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>imunify360-wsctl l7prot service            # show the current {&quot;enabled&quot;} state
imunify360-wsctl l7prot service enable     # turn rate limiting on, server-wide
imunify360-wsctl l7prot service disable    # turn rate limiting off
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></div><p>Disabling the feature stops all rate limiting immediately; your rules, default settings, and request counters are preserved and take effect again when you re-enable it.</p><div class="warning custom-block"><p class="custom-block-title">Note</p><p>Enabling the service immediately puts the <a href="#default-settings">default settings</a> in effect for <strong>all</strong> traffic: any client that exceeds the default rate — initially 300 requests per minute — is served the JavaScript challenge. Review the defaults before enabling the feature on a production server.</p></div><h2 id="default-settings" tabindex="-1"><a class="header-anchor" href="#default-settings" aria-hidden="true">#</a> Default settings</h2><p>The default settings are the catch-all rate limit applied to every request that matches no rule. They also supply the values for rule fields left empty (see <a href="#managing-rules">Managing rules</a>). The fields are:</p><table><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><span class="notranslate"><code>limit</code></span></td><td>Maximum number of requests allowed per client within the timeframe. A plain number as a string; the suffixes <span class="notranslate"><code>k</code></span> (×1,000) and <span class="notranslate"><code>m</code></span> (×1,000,000) are accepted, e.g. <span class="notranslate"><code>&quot;10k&quot;</code></span>. The special value <span class="notranslate"><code>&quot;0&quot;</code></span> triggers the action on <strong>every</strong> request.</td></tr><tr><td><span class="notranslate"><code>timeframe</code></span></td><td>The sliding-window length. A Go-style duration string using the units <span class="notranslate"><code>s</code></span>, <span class="notranslate"><code>m</code></span>, <span class="notranslate"><code>h</code></span> (compound values such as <span class="notranslate"><code>1h30m</code></span> are allowed), between <strong>10 seconds and 12 hours</strong>. For the <code>splash</code> action this is also how long a solved challenge stays valid.</td></tr><tr><td><span class="notranslate"><code>action</code></span></td><td>What happens to a request once the client exceeds the limit — one of <span class="notranslate"><code>continue</code></span>, <span class="notranslate"><code>allow</code></span>, <span class="notranslate"><code>deny</code></span>, <span class="notranslate"><code>splash</code></span> (see <a href="#actions">Actions</a>).</td></tr><tr><td><span class="notranslate"><code>log_events</code></span></td><td>Boolean. When <code>true</code>, every limit-exceeded event is written to the WebShield access log <span class="notranslate"><code>/var/log/imunify360/wafd-access.log</code></span>; when <code>false</code>, the events only appear in the debug log.</td></tr></tbody></table><p>Show the current defaults, or replace them — the settings are replaced as a whole, so <strong>all four fields are required</strong> (there is no partial update):</p><div class="notranslate"><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>imunify360-wsctl l7prot defaults
{
  &quot;limit&quot;: &quot;300&quot;,
  &quot;timeframe&quot;: &quot;1m&quot;,
  &quot;action&quot;: &quot;splash&quot;,
  &quot;log_events&quot;: true
}

imunify360-wsctl l7prot defaults &#39;{&quot;limit&quot;:&quot;500&quot;,&quot;timeframe&quot;:&quot;1m&quot;,&quot;action&quot;:&quot;splash&quot;,&quot;log_events&quot;:true}&#39;
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></div><p>The initial defaults are 300 requests per minute with the <code>splash</code> action and event logging on. Changes take effect immediately.</p><h2 id="actions" tabindex="-1"><a class="header-anchor" href="#actions" aria-hidden="true">#</a> Actions</h2><table><thead><tr><th>Action</th><th>What it does when the limit is exceeded</th></tr></thead><tbody><tr><td><span class="notranslate"><code>continue</code></span></td><td>Takes no action — the request proceeds through the normal WebShield flow. Combined with <span class="notranslate"><code>log_events</code></span>, this gives a <strong>monitor-only</strong> mode: exceeded events are logged, nothing is blocked.</td></tr><tr><td><span class="notranslate"><code>allow</code></span></td><td>Lets the request through, <strong>skipping</strong> the remaining WebShield checks (Under Attack Mode, the Anti-bot Challenge, and the ModSecurity rules). Use it to exempt trusted high-rate sources, such as your own monitoring.</td></tr><tr><td><span class="notranslate"><code>deny</code></span></td><td>Rejects the request with an HTTP 403 error.</td></tr><tr><td><span class="notranslate"><code>splash</code></span></td><td>Serves a lightweight <strong>JavaScript splash challenge</strong>. Regular browsers solve it transparently and receive a clearance cookie valid for the rule&#39;s <span class="notranslate"><code>timeframe</code></span>; while the cookie is valid their requests flow through normally even above the limit. Simple bots that cannot run the challenge never reach the application.</td></tr></tbody></table><h2 id="managing-rules" tabindex="-1"><a class="header-anchor" href="#managing-rules" aria-hidden="true">#</a> Managing rules</h2><p>A rule is created from a small JSON payload. Scope fields define <strong>which traffic the rule matches</strong>; the rate and action fields may be omitted (or set to an empty string) to <strong>inherit the current value from the default settings at match time</strong>. The fields are:</p><table><thead><tr><th>Field</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><span class="notranslate"><code>ips</code></span></td><td>at least one of the two</td><td>Array of source IPv4/IPv6 addresses or CIDR networks, e.g. <span class="notranslate"><code>[&quot;203.0.113.7&quot;, &quot;10.0.0.0/24&quot;]</code></span>.</td></tr><tr><td><span class="notranslate"><code>domains</code></span></td><td>at least one of the two</td><td>Array of domain patterns (see <a href="#domain-patterns">Domain patterns</a> below).</td></tr><tr><td><span class="notranslate"><code>limit</code></span></td><td>no</td><td>As in the <a href="#default-settings">default settings</a>. Omitted or empty — inherit the default.</td></tr><tr><td><span class="notranslate"><code>timeframe</code></span></td><td>no</td><td>As in the default settings. Omitted or empty — inherit the default.</td></tr><tr><td><span class="notranslate"><code>action</code></span></td><td>no</td><td>As in the default settings. Omitted or empty — inherit the default.</td></tr><tr><td><span class="notranslate"><code>label</code></span></td><td>no</td><td>Free-text note (up to 128 characters).</td></tr></tbody></table><p>When a rule sets <strong>both</strong> <span class="notranslate"><code>ips</code></span> and <span class="notranslate"><code>domains</code></span>, a request must match <strong>both</strong> to match the rule (a listed IP requesting a listed domain). A rule with only one of the two matches on that condition alone.</p><p>A new rule is active as soon as it is created, and is appended at the end of the evaluation order. The command prints the created rule, including its assigned <code>id</code>:</p><div class="notranslate"><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code># Throttle API scraping on all example.com subdomains, deny above 60 requests per 30 seconds:
imunify360-wsctl l7prot add &#39;{&quot;label&quot;:&quot;api burst&quot;,&quot;limit&quot;:&quot;60&quot;,&quot;timeframe&quot;:&quot;30s&quot;,&quot;action&quot;:&quot;deny&quot;,&quot;domains&quot;:[&quot;*.example.com&quot;]}&#39;

# Challenge a suspicious subnet on any domain at the default rate:
imunify360-wsctl l7prot add &#39;{&quot;label&quot;:&quot;bad subnet&quot;,&quot;action&quot;:&quot;splash&quot;,&quot;ips&quot;:[&quot;198.51.100.0/24&quot;]}&#39;

# Always let the office network through, skipping further WebShield checks:
imunify360-wsctl l7prot add &#39;{&quot;label&quot;:&quot;office&quot;,&quot;limit&quot;:&quot;0&quot;,&quot;action&quot;:&quot;allow&quot;,&quot;ips&quot;:[&quot;203.0.113.0/24&quot;]}&#39;
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></div><p>List the current rules in evaluation order (a table by default, <code>--json</code> for raw output):</p><div class="notranslate"><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>imunify360-wsctl l7prot list
+----+--------+------------+-----------+------------------+---------------+-----------+
| ID | Active | Rate       | Action    | IPs              | Domains       | Label     |
+----+--------+------------+-----------+------------------+---------------+-----------+
| 1  | true   | 60 per 30s | deny      |                  | *.example.com | api burst |
+----+--------+------------+-----------+------------------+---------------+-----------+
| 2  | true   | 300 per 1m | splash    | 198.51.100.0/24  |               | bad subnet|
|    |        | (default)  |           |                  |               |           |
+----+--------+------------+-----------+------------------+---------------+-----------+
| 3  | true   | always     | allow     | 203.0.113.0/24   |               | office    |
+----+--------+------------+-----------+------------------+---------------+-----------+
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></div><p>The <code>Rate</code> column merges the limit and the timeframe; a limit of <code>0</code> is shown as <code>always</code>. Values a rule inherits from the default settings are resolved against the current defaults and marked <span class="notranslate"><code>(default)</code></span>. The <code>ID</code> is a positive integer assigned by WebShield when the rule is created; you use it to edit or delete the rule.</p><p>Edit a rule with a partial JSON payload — only the fields present in the payload change. Setting <span class="notranslate"><code>limit</code></span>, <span class="notranslate"><code>timeframe</code></span>, or <span class="notranslate"><code>action</code></span> to <code>&quot;&quot;</code> resets the field to inherit from the defaults; <span class="notranslate"><code>ips</code></span> and <span class="notranslate"><code>domains</code></span> are replaced as whole lists (<code>null</code> clears one, but a rule must keep at least one of the two non-empty). Temporarily pausing a rule is done by setting <code>active</code> to <code>false</code>. Editing a rule does not reset its counters:</p><div class="notranslate"><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>imunify360-wsctl l7prot edit 1 &#39;{&quot;active&quot;:false}&#39;          # pause the rule (keep it for later)
imunify360-wsctl l7prot edit 1 &#39;{&quot;limit&quot;:&quot;100&quot;}&#39;           # raise the limit
imunify360-wsctl l7prot edit 1 &#39;{&quot;action&quot;:&quot;&quot;}&#39;             # reset the action to inherit the default
imunify360-wsctl l7prot edit 1 &#39;{&quot;domains&quot;:[&quot;*.example.com&quot;,&quot;example.com&quot;]}&#39;   # replace the domain list
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></div><p>Delete a rule by ID. Delete is idempotent — deleting an ID that no longer exists still succeeds:</p><div class="notranslate"><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>imunify360-wsctl l7prot delete 1
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div></div><h2 id="domain-patterns" tabindex="-1"><a class="header-anchor" href="#domain-patterns" aria-hidden="true">#</a> Domain patterns</h2><p>Each entry of a rule&#39;s <span class="notranslate"><code>domains</code></span> list is one of:</p><table><thead><tr><th>Pattern</th><th>Matches</th></tr></thead><tbody><tr><td><span class="notranslate"><code>example.com</code></span></td><td>Exactly <span class="notranslate"><code>example.com</code></span>.</td></tr><tr><td><span class="notranslate"><code>*.example.com</code></span></td><td>Any subdomain — <span class="notranslate"><code>shop.example.com</code></span>, <span class="notranslate"><code>a.b.example.com</code></span> — but <strong>not</strong> <span class="notranslate"><code>example.com</code></span> itself.</td></tr><tr><td><span class="notranslate"><code>.example.com</code></span></td><td><span class="notranslate"><code>example.com</code></span> <strong>and</strong> all its subdomains.</td></tr><tr><td><span class="notranslate"><code>*</code></span></td><td>Any domain.</td></tr></tbody></table><p>Matching is case-insensitive. Remember that all domains covered by one rule share a single per-client counter: with <span class="notranslate"><code>&quot;domains&quot;:[&quot;*.example.com&quot;]</code></span>, a client&#39;s requests to <span class="notranslate"><code>a.example.com</code></span> and <span class="notranslate"><code>b.example.com</code></span> add up against the same limit.</p><h2 id="testing-which-rule-matches" tabindex="-1"><a class="header-anchor" href="#testing-which-rule-matches" aria-hidden="true">#</a> Testing which rule matches</h2><p><span class="notranslate"><code>l7prot test</code></span> checks what the rate limiter would decide for traffic from a given source IP to a given URL, using the <strong>exact same matching as live traffic</strong>. The probe is free of side effects — it never adds to any client&#39;s request count. It is the quickest way to verify a rule&#39;s scope without generating real requests.</p><p>Both arguments are required: the source <code>IP</code> (an IPv4/IPv6 address, or a network, which is probed by its first address) and the <code>URL</code> carrying the target domain. The scheme is optional, and the path and query string are ignored — rules match on the source IP and the domain only.</p><div class="notranslate"><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>imunify360-wsctl l7prot test 203.0.113.7 example.com
imunify360-wsctl l7prot test 10.0.0.0/8 https://shop.example.com/cart?id=1
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div></div><p>When a rule matches, the command prints that rule as JSON; otherwise it reports that the default settings apply:</p><div class="notranslate"><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>imunify360-wsctl l7prot test 198.51.100.20 shop.example.com
{
  &quot;id&quot;: 2,
  &quot;active&quot;: true,
  &quot;label&quot;: &quot;bad subnet&quot;,
  &quot;limit&quot;: &quot;&quot;,
  &quot;timeframe&quot;: &quot;&quot;,
  &quot;action&quot;: &quot;splash&quot;,
  &quot;ips&quot;: [
    &quot;198.51.100.0/24&quot;
  ],
  &quot;domains&quot;: null
}

imunify360-wsctl l7prot test 192.0.2.1 other.example.org
No matching rule, default settings will be applied
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></div><div class="tip custom-block"><p class="custom-block-title">Note</p><p><span class="notranslate"><code>l7prot test</code></span> only works while the rate limiter is enabled; if the service is disabled it returns a <span class="notranslate"><code>service_disabled</code></span> error.</p></div><h2 id="monitoring" tabindex="-1"><a class="header-anchor" href="#monitoring" aria-hidden="true">#</a> Monitoring</h2><p>With <span class="notranslate"><code>log_events</code></span> set to <code>true</code> in the <a href="#default-settings">default settings</a>, every limit-exceeded event — for a rule or for the defaults — is written to the WebShield access log <span class="notranslate"><code>/var/log/imunify360/wafd-access.log</code></span>. Each entry names the matched rule by its <code>id</code> and label (or <code>defaults</code>) and the action taken:</p><div class="notranslate"><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>grep &#39;l7prot&#39; /var/log/imunify360/wafd-access.log
... l7prot: matched rule 1 (&quot;api burst&quot;), rate limit exceeded, action: deny
... l7prot: matched defaults, rate limit exceeded, action: splash
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div></div><p>Set <span class="notranslate"><code>log_events</code></span> to <code>false</code> to route these events to the debug log instead — for example when a monitor-only <code>continue</code> policy on a busy server would flood the access log.</p>`,45))])}const b=d(h,[["render",g],["__file","index.html.vue"]]);export{b as default};
